package com.jobpilot.application;import com.jobpilot.job.JobOffer;import com.jobpilot.user.User;import jakarta.persistence.*;import java.time.*;@Entity @Table(name="applications")public class JobApplication{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)@JoinColumn(name="user_id")private User user;@ManyToOne(optional=false)@JoinColumn(name="job_id")private JobOffer job;@Enumerated(EnumType.STRING)@Column(nullable=false)private ApplicationStatus status=ApplicationStatus.SAVED;@Column(length=1000)private String notes;private LocalDate appliedAt;private LocalDateTime updatedAt=LocalDateTime.now();public Long getId(){return id;}public User getUser(){return user;}public void setUser(User v){user=v;}public JobOffer getJob(){return job;}public void setJob(JobOffer v){job=v;}public ApplicationStatus getStatus(){return status;}public void setStatus(ApplicationStatus v){status=v;if(v==ApplicationStatus.APPLIED&&appliedAt==null)appliedAt=LocalDate.now();updatedAt=LocalDateTime.now();}public String getNotes(){return notes;}public void setNotes(String v){notes=v;}public LocalDate getAppliedAt(){return appliedAt;}public LocalDateTime getUpdatedAt(){return updatedAt;}}
